# ─────────────────────────────────────────────
#  AI PARSER  (google-generativeai SDK)
# ─────────────────────────────────────────────
def extract_raw_text_from_pdf(file_bytes):
    doc = fitz.open(stream=file_bytes, filetype="pdf")
    return "\n".join(page.get_text() for page in doc)
 
def extract_raw_text_from_docx(file_bytes):
    doc = Document(io.BytesIO(file_bytes))
    return "\n".join(p.text for p in doc.paragraphs)

def get_ai_cache_dir() -> str:
    cache_dir = os.path.join(os.getcwd(), ".azota_ai_cache")
    os.makedirs(cache_dir, exist_ok=True)
    return cache_dir

def build_file_cache_key(file_name: str, file_bytes: bytes) -> str:
    digest = hashlib.sha1(file_bytes).hexdigest()[:16]
    safe_name = re.sub(r"[^A-Za-z0-9._-]+", "_", file_name or "file")
    return f"{safe_name}_{digest}"

def get_ai_cache_path(cache_key: str) -> str:
    return os.path.join(get_ai_cache_dir(), f"{cache_key}.json")

def load_ai_cache(cache_key: str) -> dict:
    if not cache_key:
        return {}
    path = get_ai_cache_path(cache_key)
    if not os.path.exists(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            payload = json.load(f)
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}

def save_ai_cache(cache_key: str, payload: dict) -> None:
    if not cache_key:
        return
    path = get_ai_cache_path(cache_key)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)

def merge_questions_by_qnum(existing_questions: list, new_questions: list) -> list:
    merged = {}
    for question in existing_questions or []:
        normalized = normalize_question(question, question.get("q_num", 1) if isinstance(question, dict) else 1)
        merged[normalized.get("q_num")] = normalized
    for question in new_questions or []:
        normalized = normalize_question(question, question.get("q_num", 1) if isinstance(question, dict) else 1)
        merged[normalized.get("q_num")] = normalized
    return [merged[key] for key in sorted(k for k in merged.keys() if isinstance(k, int))]

def detect_question_blocks(raw_text: str) -> list:
    text = (raw_text or "").strip()
    if not text:
        return []

    pattern = re.compile(
        r"(?im)(?=^(?:\s*(?:câu|cau|câu hỏi|cau hoi)\s*\d+[\s\.:)])|(?:\s*\d+[\s\.:)]))"
    )
    positions = [match.start() for match in pattern.finditer(text)]
    if not positions:
        return []
    if positions[0] != 0:
        positions.insert(0, 0)
    positions.append(len(text))

    blocks = []
    for i in range(len(positions) - 1):
        block = text[positions[i]:positions[i + 1]].strip()
        if len(block) > 20:
            blocks.append(block)
    return blocks
 
def _get_gemini_model(api_key: str):
    try:
        import google.generativeai as genai
        genai.configure(api_key=api_key)
        
        # SỬA Ở ĐÂY: Dùng đúng tên có trong list của bạn
        # Thêm tiền tố 'models/' vào trước để chắc chắn 100%
        return genai.GenerativeModel("models/gemini-flash-latest") 
        
    except Exception as e:
        st.error(f"Lỗi: {e}")
        return None
 
def split_text_for_ai(raw_text: str, chunk_size: int = 12000) -> list:
    text = (raw_text or "").strip()
    if not text:
        return []

    chunks = []
    start = 0
    while start < len(text):
        end = min(start + chunk_size, len(text))
        if end < len(text):
            split_at = text.rfind("\n", start, end)
            if split_at <= start:
                split_at = text.rfind(" ", start, end)
            if split_at > start:
                end = split_at
        chunk = text[start:end].strip()
        if chunk:
            chunks.append(chunk)
        start = max(end, start + 1)
    return chunks

def _coerce_parsed_questions(parsed) -> list:
    if isinstance(parsed, dict):
        for key in ("questions", "data", "items", "results"):
            if isinstance(parsed.get(key), list):
                parsed = parsed[key]
                break
        else:
            parsed = [parsed]
    return parsed if isinstance(parsed, list) else []

def _extract_balanced_json_objects(text_out: str) -> list:
    objects = []
    start = None
    depth = 0
    in_string = False
    escaped = False

    for i, ch in enumerate(text_out):
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue

        if ch == '"':
            in_string = True
            continue

        if ch == "{":
            if depth == 0:
                start = i
            depth += 1
        elif ch == "}":
            if depth > 0:
                depth -= 1
                if depth == 0 and start is not None:
                    snippet = text_out[start:i + 1]
                    try:
                        objects.append(json.loads(snippet))
                    except Exception:
                        pass
                    start = None
    return objects

def _parse_questions_from_response(text_out: str) -> list:
    cleaned = (text_out or "").strip()
    if not cleaned:
        return []

    fenced = re.sub(r"^```(?:json)?\s*", "", cleaned)
    fenced = re.sub(r"\s*```$", "", fenced).strip()

    try:
        return _coerce_parsed_questions(json.loads(fenced))
    except json.JSONDecodeError:
        pass

    for match in re.finditer(r"(\[[\s\S]*\]|\{[\s\S]*\})", fenced):
        snippet = match.group(1).strip()
        try:
            parsed = json.loads(snippet)
            coerced = _coerce_parsed_questions(parsed)
            if coerced:
                return coerced
        except Exception:
            continue

    return _extract_balanced_json_objects(fenced)

def _ai_parse_questions_chunk(segment_text: str, model) -> list:
    prompt = (
        "Ban la parser cau hoi trac nghiem.\n"
        "Tra ve DUY NHAT mot JSON array hop le.\n"
        "Moi phan tu co dang: "
        '{"q_num":1,"question":"...","options":["A. ...","B. ...","C. ...","D. ..."],"answer":"A"}.\n'
        "Neu khong ro dap an thi de answer rong.\n"
        "Khong viet giai thich, khong markdown, khong text ngoai JSON.\n"
        "Van ban:\n" + segment_text
    )

    response = model.generate_content(
        prompt,
        generation_config={
            "temperature": 0.1,
            "max_output_tokens": 4096,
            "response_mime_type": "application/json",
        },
    )
    return _parse_questions_from_response(getattr(response, "text", ""))

def ai_parse_questions(segment_text: str, api_key: str) -> list:
    """Parse một đoạn văn bản (segment) sang JSON."""
    model = _get_gemini_model(api_key)
    if not model:
        return []
    try:
        # Xóa [:9000] để nhận toàn bộ đoạn segment được truyền vào
        prompt = (
            "Bạn là parser câu hỏi trắc nghiệm chuyên nghiệp.\n"
            "Trích xuất TẤT CẢ câu hỏi từ văn bản sau sang định dạng JSON.\n"
            "Văn bản: " + segment_text 
        )
        
        response = model.generate_content(
            prompt,
            generation_config={
                "temperature": 0.1, 
                "max_output_tokens": 8192,
                "response_mime_type": "application/json" 
            },
        )
        
        text_out = response.text.strip()
        parsed = json.loads(text_out)
        
        if isinstance(parsed, dict):
            for key in ("questions", "data", "items", "results"):
                if isinstance(parsed.get(key), list):
                    parsed = parsed[key]
                    break
            else:
                parsed = [parsed]
        if not isinstance(parsed, list):
            return []

        return [normalize_question(q, i + 1) for i, q in enumerate(parsed)]
    except Exception as e:
        st.error(f"Lỗi phân đoạn: {e}")
        return []
 
def ai_parse_questions(segment_text: str, api_key: str) -> list:
    """Robust parser for Gemini free tier: chia nhỏ input và cứu JSON bị cắt."""
    model = _get_gemini_model(api_key)
    if not model:
        return []

    chunks = split_text_for_ai(segment_text)
    all_questions = []
    had_error = False

    for chunk_index, chunk in enumerate(chunks, start=1):
        try:
            parsed_questions = _ai_parse_questions_chunk(chunk, model)
            if parsed_questions:
                base = len(all_questions)
                all_questions.extend(
                    normalize_question(q, base + i + 1) for i, q in enumerate(parsed_questions)
                )
        except Exception as e:
            had_error = True
            st.warning(f"Lỗi phân đoạn {chunk_index}: {e}")

    if all_questions:
        for i, q in enumerate(all_questions, start=1):
            q["q_num"] = i
        return all_questions

    if had_error:
        st.error("AI không trả về JSON hoàn chỉnh sau khi đã chia nhỏ nội dung.")
    return []

def normalize_options(raw_options) -> list:
    if raw_options is None:
        return []

    if isinstance(raw_options, dict):
        normalized = []
        for key, value in raw_options.items():
            letter = str(key).strip().upper()[:1]
            content = "" if value is None else str(value).strip()
            if not content:
                continue
            normalized.append(f"{letter}. {content}" if letter in "ABCD" else content)
        return normalized[:4]

    if isinstance(raw_options, str):
        lines = [line.strip(" -*\t") for line in raw_options.splitlines() if line.strip()]
        return lines[:4]

    if isinstance(raw_options, (list, tuple)):
        normalized = []
        for item in raw_options:
            if isinstance(item, dict):
                letter = str(item.get("label") or item.get("key") or item.get("option") or "").strip().upper()[:1]
                content = str(
                    item.get("text")
                    or item.get("content")
                    or item.get("value")
                    or item.get("option_text")
                    or ""
                ).strip()
                if not content:
                    continue
                normalized.append(f"{letter}. {content}" if letter in "ABCD" else content)
            elif item is not None:
                text = str(item).strip()
                if text:
                    normalized.append(text)
        return normalized[:4]

    text = str(raw_options).strip()
    return [text] if text else []

def normalize_question(raw_question, fallback_q_num: int) -> dict:
    if not isinstance(raw_question, dict):
        raw_question = {"question": str(raw_question or "")}

    q_num = raw_question.get("q_num", fallback_q_num)
    try:
        q_num = int(q_num)
    except Exception:
        q_num = fallback_q_num

    answer = str(raw_question.get("answer", "")).strip().upper()[:1]
    if not answer:
        answer_text = str(raw_question.get("correct_answer") or raw_question.get("correct") or "").strip().upper()
        match = re.match(r"^([A-D])", answer_text)
        if match:
            answer = match.group(1)

    return {
        "q_num": q_num,
        "question": str(raw_question.get("question", "")).strip(),
        "options": normalize_options(raw_question.get("options")),
        "answer": answer,
    }

def ai_parse_question_range(raw_text: str, api_key: str, start_q: int = 1, end_q: int | None = None, batch_size: int = 20) -> tuple[list, int]:
    blocks = detect_question_blocks(raw_text)
    total_detected = len(blocks)

    if blocks:
        safe_start = max(1, start_q)
        safe_end = min(end_q or total_detected, total_detected)
        if safe_start > safe_end:
            return [], total_detected

        model = _get_gemini_model(api_key)
        if not model:
            return [], total_detected

        parsed_questions = []
        selected_blocks = blocks[safe_start - 1:safe_end]
        for offset in range(0, len(selected_blocks), max(1, batch_size)):
            batch_blocks = selected_blocks[offset:offset + max(1, batch_size)]
            batch_text = "\n\n".join(batch_blocks)
            batch_questions = _ai_parse_questions_chunk(batch_text, model)
            base_q_num = safe_start + offset
            for i, question in enumerate(batch_questions):
                normalized = normalize_question(question, base_q_num + i)
                normalized["q_num"] = base_q_num + i
                parsed_questions.append(normalized)
        return parsed_questions, total_detected

    parsed_questions = ai_parse_questions(raw_text, api_key)
    return parsed_questions, len(parsed_questions)

def ai_analyze_image(image_bytes: bytes, api_key: str) -> str:
    """Gửi ảnh câu hỏi lên Gemini để giải và phân tích."""
    model = _get_gemini_model(api_key)
    if not model:
        return ""
    try:
        from PIL import Image as PILImage
        img = PILImage.open(io.BytesIO(image_bytes))
        response = model.generate_content(
            ["Hãy giải bài tập trong ảnh này chi tiết, nếu là câu hỏi trắc nghiệm hãy chỉ rõ đáp án đúng và giải thích tại sao.", img],
            generation_config={"temperature": 0.2, "max_output_tokens": 2048},
        )
        return response.text.strip()
    except ImportError:
        st.error("❌ Thiếu thư viện Pillow: chạy `pip install Pillow`")
        return ""
    except Exception as e:
        st.error(f"Lỗi phân tích ảnh: {e}")
        return ""
 
# ─────────────────────────────────────────────
#  PDF PARSER
# ─────────────────────────────────────────────
def extract_from_pdf(file_bytes):
    import fitz  # PyMuPDF
    import re
    doc = fitz.open(stream=file_bytes, filetype="pdf")
    questions, current_q = [], None
    
    # Mã màu đỏ thường gặp trong PDF
    RED_COLORS = (16711680, 13572096, 0xFF0000, 0xCF0000, 13574151)

    for page in doc:
        blocks = page.get_text("dict")["blocks"]
        for b in blocks:
            if "lines" not in b: continue
            for l in b["lines"]:
                for s in l["spans"]:
                    text = s["text"].strip()
                    if not text: continue
                    
                    # Kiểm tra màu đỏ hoặc gạch chân (để lấy đáp án)
                    is_red = s["color"] in RED_COLORS
                    is_ul = bool(s["flags"] & 4)
                    
                    # 1. Nhận diện câu hỏi: "Câu 1.", "Câu 1:", "Câu 1 " (loại bỏ [: hoặc .] ở Regex)
                    if re.match(r'^(Câu|Câu hỏi)\s*\d+[\s.:]', text, re.I):
                        if current_q: questions.append(current_q)
                        current_q = {
                            'question': text, 
                            'options': [], 
                            'answer': '', 
                            'q_num': len(questions) + 1
                        }
                    
                    # 2. Nhận diện đáp án: "a.", "b.", "c.", "d." hoặc "A.", "B."...
                    elif re.match(r'^[a-dA-D][\s.:)]', text):
                        if current_q is not None:
                            current_q['options'].append(text)
                            if is_red or is_ul: 
                                # Lấy chữ cái đầu (A, B, C, hoặc D)
                                current_q['answer'] = text[0].upper()
                    
                    # 3. Nội dung nối tiếp
                    elif current_q:
                        if not current_q['options']:
                            # Nối dài nội dung câu hỏi
                            current_q['question'] += " " + text
                        else:
                            # Nối dài nội dung đáp án cuối cùng
                            current_q['options'][-1] += " " + text
                            if is_red or is_ul:
                                current_q['answer'] = current_q['options'][-1][0].upper()

    if current_q: questions.append(current_q)
    doc.close()
    return questions
 
# ─────────────────────────────────────────────
#  DOCX PARSER
# ─────────────────────────────────────────────
def extract_from_docx(file_bytes):
    doc = Document(io.BytesIO(file_bytes))
    questions, current_q = [], None
    body = doc.element.body
    para_idx = table_idx = 0
 
    for child in body:
        tag = child.tag.split('}')[-1] if '}' in child.tag else child.tag
 
        if tag == 'p':
            if para_idx >= len(doc.paragraphs): para_idx += 1; continue
            para = doc.paragraphs[para_idx]; text = para.text.strip(); para_idx += 1
            if not text: continue
            has_ul = has_red = has_hl = False
            for run in para.runs:
                if run.underline: has_ul = True
                if run.font.color and run.font.color.rgb:
                    if str(run.font.color.rgb) in ('FF0000','CF0000','CC0000'): has_red = True
                try:
                    if run.font.highlight_color not in (None, 0): has_hl = True
                except ValueError: pass
            is_list = hasattr(para,'_p') and para._p.pPr is not None and para._p.pPr.numPr is not None
            q_match = re.match(r'^(?:(?:Câu|Câu hỏi)\s*)?(\d+)[:.]', text, re.I)
            if (q_match and not re.match(r'^[A-D][.:]', text, re.I)) or is_list:
                if current_q: questions.append(current_q)
                q_num = int(q_match.group(1)) if q_match else len(questions)+1
                current_q = {'question': text, 'options': [], 'answer': '', 'q_num': len(questions)+1, 'original_num': q_num}
                continue
            opt_m = re.match(r'^([a-dA-D])[.:)]\s*(.*)', text)
            if opt_m and current_q is not None:
                letter = opt_m.group(1).upper()
                current_q['options'].append(f"{letter}. {opt_m.group(2)}")
                if has_ul or has_red or has_hl: current_q['answer'] = letter
                continue
            if current_q and not re.match(r'^(Câu|Phần|Chương|C\d+)', text, re.I):
                oc = len(current_q['options'])
                if oc < 4:
                    letter = ['A','B','C','D'][oc]
                    current_q['options'].append(f"{letter}. {text}")
                    if has_ul or has_red or has_hl: current_q['answer'] = letter
                elif current_q['options']: current_q['options'][-1] += ' ' + text
 
        elif tag == 'tbl':
            if table_idx >= len(doc.tables): table_idx += 1; continue
            table = doc.tables[table_idx]; table_idx += 1
            if current_q is None: continue
            for row in table.rows:
                nc = len(row.cells)
                for ci, cell in enumerate(row.cells):
                    pl = (['A','B'] if ci==0 else ['C','D']) if nc>=2 else ['A','B','C','D']
                    pi = 0
                    for p in cell.paragraphs:
                        pt = p.text.strip()
                        if not pt: continue
                        pu = pr = ph = False; ul_letters = set()
                        for run in p.runs:
                            rt = run.text.strip()
                            if not rt: continue
                            if run.underline: pu = True
                            if run.font.color and run.font.color.rgb:
                                if str(run.font.color.rgb) in ('FF0000','CF0000','CC0000'): pr = True
                            try:
                                if run.font.highlight_color not in (None,0): ph = True
                            except ValueError: pass
                            if run.underline or pr or ph:
                                lm = re.match(r'^([a-dA-D])[.:]?\s*$', rt)
                                if lm: ul_letters.add(lm.group(1).upper())
                        for line in pt.split('\n'):
                            line = line.strip()
                            if not line: continue
                            lc = re.match(r'^([a-d])[.:)]\s*(.*)', line)
                            if lc:
                                letter = lc.group(1).upper(); content = lc.group(2)
                                ex = set(o[0] for o in current_q['options'] if o)
                                if letter in ex:
                                    for oi,opt in enumerate(current_q['options']):
                                        if opt.startswith(f"{letter}."): current_q['options'][oi] += ' ' + content; break
                                else: current_q['options'].append(f"{letter}. {content}")
                                if letter in ul_letters or pu or pr or ph: current_q['answer'] = letter
                                continue
                            if pi < len(pl):
                                letter = pl[pi]; ex = set(o[0] for o in current_q['options'] if o)
                                if letter in ex:
                                    if current_q['options']: current_q['options'][-1] += ' ' + line
                                else: current_q['options'].append(f"{letter}. {line}"); pi += 1
                                if pu or pr or ph: current_q['answer'] = current_q['options'][-1][0]
    if current_q: questions.append(current_q)
    return questions
 
