def compute_score(history):
    return sum(1 for v in history.values() if v.get('correct') is True)
 
def render_q_grid(subset, history, current_idx):
    cells = []
    for i in range(len(subset)):
        if i == current_idx: css = "q-dot-current"
        elif i in history: css = "q-dot-correct" if history[i].get('correct') else "q-dot-wrong"
        else: css = "q-dot-unanswered"
        cells.append(f'<div class="q-dot {css}">{i+1}</div>')
    st.markdown(f'<div class="q-grid">{"".join(cells)}</div>', unsafe_allow_html=True)
 
